Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

(* [comment removed for export] *)
Definition clip_neg_d (d s n : Z) : Z * Z * Z := if d <? 0 then (0, s - d, n + d) else (d, s, n).
Definition clip_neg_s (d s n : Z) : Z * Z * Z := if s <? 0 then (d - s, 0, n + s) else (d, s, n).
Definition clip_hang (off n size : Z) : Z := if 0 <? off + n - size then n - (off + n - size) else n.
Definition clip_axis2 (dsize ssize d s n : Z) : Z * Z * Z :=
  let '(d1, s1, n1) := clip_neg_d d s n in
  let '(d2, s2, n2) := clip_neg_s d1 s1 n1 in
  let n3 := clip_hang d2 n2 dsize in
  let n4 := clip_hang s2 n3 ssize in
  (d2, s2, n4).
(* [comment removed for export] *)
Definition clip_axis1 (dsize d n : Z) : Z * Z :=
  let '(d1, n1) := (if d <? 0 then (0, n + d) else (d, n)) in
  (d1, clip_hang d1 n1 dsize).

Record roprect : Type := mkRop { r_dx : Z; r_dy : Z; r_dw : Z; r_dh : Z; r_sx : Z; r_sy : Z }.
(* [comment removed for export] *)
Definition rop_clip (dpixw dpixh spixw spixh : Z) (r : roprect) : roprect :=
  let '(dx, sx, dw) := clip_axis2 dpixw spixw (r_dx r) (r_sx r) (r_dw r) in
  let '(dy, sy, dh) := clip_axis2 dpixh spixh (r_dy r) (r_sy r) (r_dh r) in
  mkRop dx dy dw dh sx sy.
Definition rop_empty (r : roprect) : Prop := r_dw r <= 0 \/ r_dh r <= 0.
Inductive roparm : Type := RopWordAligned | RopVAligned | RopGeneral.
Definition rop_arm (r : roprect) : roparm :=
  if (r_dx r mod 32 =? 0) && (r_sx r mod 32 =? 0) then RopWordAligned
  else if r_dx r mod 32 =? r_sx r mod 32 then RopVAligned else RopGeneral.
(* [comment removed for export] *)
Record unirect : Type := mkUni { u_dx : Z; u_dy : Z; u_dw : Z; u_dh : Z }.
Definition uni_clip (dpixw dpixh : Z) (u : unirect) : unirect :=
  let '(dx, dw) := clip_axis1 dpixw (u_dx u) (u_dw u) in
  let '(dy, dh) := clip_axis1 dpixh (u_dy u) (u_dh u) in
  mkUni dx dy dw dh.
Definition uni_empty (u : unirect) : Prop := u_dw u <= 0 \/ u_dh u <= 0.
Definition uni_wordaligned (u : unirect) : bool := u_dx u mod 32 =? 0.

(* [comment removed for export] *)
Lemma clip_axis2_inside : forall dsize ssize d s n d' s' n',
  clip_axis2 dsize ssize d s n = (d', s', n') -> 0 < n' ->
  0 <= d' /\ 0 <= s' /\ d' + n' <= dsize /\ s' + n' <= ssize /\ n' <= n.
Proof.
